package com.tripnest.controller; import com.tripnest.dto.ApiDtos.Contact; import com.tripnest.entity.ContactMessage; import com.tripnest.repository.ContactMessageRepository; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/contact") public class ContactController{final ContactMessageRepository repo; public ContactController(ContactMessageRepository r){repo=r;} @PostMapping public Map<String,String> send(@Valid @RequestBody Contact x){ContactMessage m=new ContactMessage();m.setName(x.name());m.setEmail(x.email());m.setSubject(x.subject());m.setMessage(x.message());repo.save(m);return Map.of("message","Thanks — your message has been received.");} }
